for i, ch in enumerate(seq):
    if ch in '([{<':
        stack.append((ch, i))
    elif ch in ')]}>':
        if not stack:
            print(f"Error at {i}: {ch}")
            break
        top, idx = stack.pop()
        if (top, ch) not in [('(', ')'), ('[', ']'), ('{', '}'), ('<', '>')]:
            print(f"Error at {i}: mismatch {top} and {ch}")
            break
print(f"Stack after processing: {stack}")

