stack = []
input_str = "[ ( < { [ ( ) ] } >"
for char in input_str:
    if char in "([{":
        stack.append(char)
    elif char in ")]}":
        if stack:
            stack.pop()
    elif char == ">":
        if stack:
            stack.pop()

# Remaining items in stack need to be closed
closing_brackets = []
while stack:
    opening = stack.pop()
    if opening == "[":
        closing_brackets.append("]")
    elif opening == "(":
        closing_brackets.append(")")
    elif opening == "{":
        closing_brackets.append("}")
    elif opening == "<":
        closing_brackets.append(">")

print(" ".join(closing_brackets))

